"""Strict bounded acoustic metadata. No PCM, words, or future audio."""

import json
import math
from pathlib import Path

# Generated by scripts/sync-embodiment-style.mjs from contracts/embodiment-style.v1.json.
STYLE_CONTRACT = json.loads(
    (Path(__file__).resolve().parent / "embodiment_style.json").read_text("utf-8")
)
STYLE_AXES = STYLE_CONTRACT["axes"]
NEUTRAL_STYLE = STYLE_CONTRACT["default"]


def number(value, low, high, integer=False):
    return (
        type(value) in ((int,) if integer else (int, float))
        and math.isfinite(value)
        and low <= value <= high
    )


def validate_activity(activity):
    if activity is None:
        return None
    if (
        not isinstance(activity, dict)
        or not {"energy", "playbackId", "speaking"} <= set(activity)
        or set(activity) - {"energy", "playbackId", "speaking", "prosody", "style"}
        or not number(activity["energy"], 0, 1)
        or type(activity["speaking"]) is not bool
        or (
            activity["playbackId"] is not None
            and (
                not isinstance(activity["playbackId"], str)
                or not 1 <= len(activity["playbackId"]) <= 128
            )
        )
    ):
        raise ValueError("Invalid bounded acoustic activity")
    prosody = activity.get("prosody")
    if prosody is not None and (
        not isinstance(prosody, dict)
        or not {"throughSample", "sampleRate", "envelope", "phase", "accent", "leadMs"}
        <= set(prosody)
        or set(prosody)
        - {
            "throughSample",
            "sampleRate",
            "envelope",
            "phase",
            "accent",
            "leadMs",
            "available",
        }
        or not number(prosody["throughSample"], 0, 2**48, True)
        or not number(prosody["sampleRate"], 8000, 192000, True)
        or not isinstance(prosody["envelope"], list)
        or not 1 <= len(prosody["envelope"]) <= 12
        or not all(number(value, 0, 1) for value in prosody["envelope"])
        or prosody["phase"] not in ("onset", "speech", "pause")
        or not number(prosody["accent"], 0, 1)
        or not number(prosody["leadMs"], 0, 4000)
        or activity["playbackId"] is None
    ):
        raise ValueError("Invalid consumed speech context")
    style = activity.get("style")
    if style is not None and (
        not isinstance(style, dict)
        or set(style) != set(STYLE_AXES)
        or not all(number(style[axis], *STYLE_AXES[axis]) for axis in STYLE_AXES)
    ):
        raise ValueError("Invalid bounded delivery style")
    available = (prosody or {}).get("available")
    if available is not None and (
        not isinstance(available, dict)
        or not {"startSample", "stepSamples", "energy", "finalSample"} <= set(available)
        or set(available)
        - {"startSample", "stepSamples", "energy", "finalSample", "accent"}
        or not number(available["startSample"], 0, 2**48, True)
        or not number(
            available["stepSamples"], 1, prosody["sampleRate"] * 0.05 + 1, True
        )
        or not isinstance(available["energy"], list)
        or not 1 <= len(available["energy"]) <= 30
        or not all(number(value, 0, 1) for value in available["energy"])
        or (
            "accent" in available
            and (
                not isinstance(available["accent"], list)
                or len(available["accent"]) != len(available["energy"])
                or not all(number(value, 0, 1) for value in available["accent"])
            )
        )
        or abs(available["startSample"] - prosody["throughSample"])
        > prosody["sampleRate"]
        or (
            available["finalSample"] is not None
            and not number(
                available["finalSample"], available["startSample"], 2**48, True
            )
        )
    ):
        raise ValueError("Invalid available PCM context")
    return activity


def delivery_style(activity):
    """The validated audible-segment style, or the neutral style when absent."""
    return (activity or {}).get("style") or NEUTRAL_STYLE


MIN_ACCENT_MS = 580
PITCH_ACCENT_MINIMUM = 0.25


def available_accents(activity, minimum, maximum):
    """(score, milliseconds) of already submitted accents inside [minimum, maximum].

    No prediction beyond the submitted buffer; an accent earlier than the
    shortest native transition is discarded, never rescheduled late. A pitch
    accent qualifies on its own; without pitch data only energy peaks do.
    """
    prosody = (activity or {}).get("prosody") or {}
    available = prosody.get("available")
    if not available or not activity["speaking"]:
        return []
    rate = prosody["sampleRate"]
    start = prosody["throughSample"] + prosody["leadMs"] * rate / 1000
    candidates = []
    energies = available["energy"]
    pitches = available.get("accent")
    for i in range(1, len(energies) - 1):
        sample = available["startSample"] + (i + 0.5) * available["stepSamples"]
        if available["finalSample"] is not None and sample >= available["finalSample"]:
            continue
        milliseconds = (sample - start) * 1000 / rate
        if not max(MIN_ACCENT_MS, minimum) <= milliseconds <= maximum:
            continue
        score = 0.0
        if (
            energies[i] >= max(0.08, energies[i - 1], energies[i + 1])
            and energies[i] > min(energies[i - 1], energies[i + 1]) * 1.15
        ):
            score = min(energies[i], (energies[i - 1] + energies[i + 1]) / 2)
        if (
            pitches
            and pitches[i] >= PITCH_ACCENT_MINIMUM
            and pitches[i] >= max(pitches[i - 1], pitches[i + 1])
        ):
            score = max(score, pitches[i])
        if score > 0:
            candidates.append((score, milliseconds))
    return candidates


def accent_deadline_ms(activity, maximum):
    """Select only an already available sustained envelope or pitch maximum."""
    candidates = available_accents(activity, MIN_ACCENT_MS, maximum)
    return max(candidates)[1] if candidates else None
